def calories(minutes, rate):
    return minutes * rate

def total_calories(run_min, bike_min):
    return calories(run_min, 10) + calories(bike_min, 8)

def summary(run_min, bike_min):
    return f"You burned {total_calories(run_min, bike_min)} calories today."
